-- Hosbah (MH-575 H7): a reduced OTLP span. Storage keeps only root/server spans, spans with an
-- error, and spans slower than internal/apm's threshold — see internal/apm/ingest.go — so unlike
-- rum_samples this is never the complete original trace, only the interesting parts of it. attrs
-- is a small, capped, scrubbed subset of the span's attributes (never request bodies or anything
-- matching internal/apm's secret-looking-key deny list).
ALTER TABLE apm_spans ADD CONSTRAINT apm_spans_kind_check CHECK (kind IN ('server', 'client', 'internal', 'producer', 'consumer', 'root'));
CREATE INDEX apm_spans_app_created_idx ON apm_spans (team_id, app_id, created_at);
CREATE INDEX apm_spans_app_route_idx ON apm_spans (team_id, app_id, http_method, http_route, start_time);
CREATE INDEX apm_spans_trace_idx ON apm_spans (team_id, app_id, trace_id);
CREATE INDEX apm_spans_created_idx ON apm_spans (created_at);
